testo:
{
 "genere": "prevedi",
 "titolo": "Cosa restituisce?",
 "consegna": "Leggi ogni pezzo di codice e scrivi cosa restituisce `run()`, senza eseguirlo. Poi confronta con la risposta vera.",
 "modalita": "previsioni",
 "previsioni": [
  {
   "codice": "extends RefCounted


func run() -> int:
	var label := Label.new()
	label.add_theme_font_size_override("font_size", 24)
	return label.get_theme_font_size("font_size")
",
   "domanda": "Che dimensione restituisce `get_theme_font_size("font_size")`?",
   "spiegazione": "L'override impostato con `add_theme_font_size_override` viene memorizzato direttamente nel nodo e restituito dalla funzione di lettura del tema."
  },
  {
   "codice": "extends RefCounted


func run() -> String:
	var file_name: String = "OpenSans-Regular.ttf"
	var is_dynamic: bool = file_name.ends_with(".ttf") or file_name.ends_with(".otf")
	return "Dinamico" if is_dynamic else "Statico"
",
   "domanda": "Che testo restituisce `run()`?",
   "spiegazione": "Il nome del file termina con l'estensione `.ttf`, quindi la verifica con `ends_with` risulta vera e la funzione restituisce "Dinamico"."
  },
  {
   "codice": "extends RefCounted


func run() -> bool:
	var label := Label.new()
	label.add_theme_font_size_override("font_size", 32)
	label.remove_theme_font_size_override("font_size")
	return label.has_theme_font_size_override("font_size")
",
   "domanda": "Cosa restituisce `has_theme_font_size_override("font_size")` alla fine?",
   "spiegazione": "Dopo aver aggiunto l'override e averlo rimosso con `remove_theme_font_size_override`, il nodo non possiede più quell'override personalizzato, quindi restituisce `false`."
  },
  {
   "codice": "extends RefCounted


func run() -> int:
	var label := Label.new()
	label.add_theme_constant_override("outline_size", 4)
	return label.get_theme_constant("outline_size")
",
   "domanda": "Quanto vale la costante di contorno (outline size) alla fine?",
   "spiegazione": "Le proprietà numeriche dei temi come la dimensione del contorno si gestiscono come costanti. `add_theme_constant_override` imposta correttamente il valore per "outline_size"."
  },
  {
   "codice": "extends RefCounted


func run() -> Color:
	var label := Label.new()
	label.add_theme_color_override("font_shadow_color", Color(0, 0, 0, 1))
	return label.get_theme_color("font_shadow_color")
",
   "domanda": "Quale colore restituisce `get_theme_color("font_shadow_color")`?",
   "spiegazione": "L'override applicato imposta il colore dell'ombra del testo sul nero opaco `Color(0, 0, 0, 1)`, che viene poi letto e restituito dal nodo."
  }
 ]
}
